class PairCounter {
  private small: number[];
  private big: number[];
  constructor(small: number[], big: number[]) {
    this.small = small;
    this.big = [...big];
  }

  bump(index: number, delta: number): void {
    this.big[index] += delta;
  }

  pairs(target: number): number {
    let total = 0;
    for (const x of this.small)
      for (const y of this.big)
        if (x + y === target) total++;
    return total;
  }
}

