class PairCounter {
  private small: number[];
  private big: number[];
  private count = new Map<number, number>();

  constructor(small: number[], big: number[]) {
    this.small = small;
    this.big = [...big];
    for (const v of big) this.count.set(v, (this.count.get(v) ?? 0) + 1);
  }

  bump(index: number, delta: number): void {
    const old = this.big[index];
    this.count.set(old, this.count.get(old)! - 1);
    const now = old + delta;
    this.big[index] = now;
    this.count.set(now, (this.count.get(now) ?? 0) + 1);
  }

  pairs(target: number): number {
    let total = 0;
    for (const x of this.small) total += this.count.get(target - x) ?? 0;
    return total;
  }
}

